package config

import (
	"fmt"
	"strings"

	"gopkg.in/yaml.v3"
)

const UALabGeneratedMarker = "# Generated by UALab"

// ParseUALabGeminiYAML strictly parses a pasted "# Generated by UALab" YAML block
// into GeminiHeaderDefaults. It rejects "auto" and requires an explicit User-Agent.
func ParseUALabGeminiYAML(raw string) (GeminiHeaderDefaults, error) {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return GeminiHeaderDefaults{}, fmt.Errorf("paste the %s YAML block generated by UALab", UALabGeneratedMarker)
	}
	if !strings.Contains(trimmed, UALabGeneratedMarker) {
		return GeminiHeaderDefaults{}, fmt.Errorf("input must contain the %q header produced by UALab", UALabGeneratedMarker)
	}

	var v8Doc struct {
		Upstream struct {
			Gemini struct {
				HeaderDefaults GeminiHeaderDefaults `yaml:"header-defaults"`
			} `yaml:"gemini"`
		} `yaml:"upstream"`
		Legacy GeminiHeaderDefaults `yaml:"gemini-header-defaults"`
	}
	if err := yaml.Unmarshal([]byte(trimmed), &v8Doc); err != nil {
		return GeminiHeaderDefaults{}, fmt.Errorf("invalid UALab YAML: %w", err)
	}

	hd := v8Doc.Upstream.Gemini.HeaderDefaults
	if hd.UserAgent == "" && v8Doc.Legacy.UserAgent != "" {
		hd = v8Doc.Legacy
	}

	tmpCfg := &Config{GeminiHeaderDefaults: hd}
	tmpCfg.SanitizeGeminiHeaderDefaults()
	hd = tmpCfg.GeminiHeaderDefaults

	if hd.UserAgent == "" {
		return GeminiHeaderDefaults{}, fmt.Errorf("UALab YAML is missing upstream.gemini.header-defaults.user-agent")
	}
	if err := tmpCfg.ValidateUserAgents(); err != nil {
		return GeminiHeaderDefaults{}, err
	}
	return hd, nil
}
